// Offline cache. On install the whole app is precached from precache-manifest.json (generated by
// tools/gen-precache.mjs) so every screen, setup guide and the PDF engine work with no service
// after the first load, not just the screens opened while online. CORE is the minimum that must
// cache even if the manifest fetch fails, so the app still opens offline.
const CACHE = 'fishtape-v77-offline';
const CORE = ['./', './index.html', './manifest.webmanifest', './css/tokens.css', './css/app.css', './js/app.js'];

// put() one by one rather than addAll(): addAll fails the whole install ("Entry already exists")
// when the previous worker is writing the same file to this cache, and one 404 would abort it all.
async function precache() {
  const c = await caches.open(CACHE);
  let list = CORE;
  try {
    const res = await fetch('./precache-manifest.json', { cache: 'no-cache' });
    if (res.ok) list = [...new Set([...CORE, ...(await res.json())])];
  } catch { /* offline or missing: fall back to CORE */ }
  await Promise.all(list.map((u) => fetch(u, { cache: 'no-cache' })
    .then((res) => (res.ok ? c.put(u, res) : null)).catch(() => null)));
}
self.addEventListener('install', (e) => { e.waitUntil(precache().then(() => self.skipWaiting())); });
self.addEventListener('activate', (e) => {
  e.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k)))).then(() => self.clients.claim()));
});
// Network first so updates land straight away; fall back to the cache offline.
// API traffic is never cached: it carries company data and the sync queue handles offline.
self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== location.origin || url.pathname.startsWith('/api/')) return;
  e.respondWith(fetch(req).then((res) => {
    if (res.ok) {
      const copy = res.clone();
      caches.open(CACHE).then((c) => c.put(req, copy));
    }
    return res;
  }).catch(() => caches.match(req).then((r) => r || caches.match('./index.html'))));
});

// Web Share Target (manifest.webmanifest share_target): files shared to the installed app from another
// app arrive here as a multipart POST. They are kept in IndexedDB "fishtape-share" (the same store and
// shape js/lib/files-share.js reads) and the Files screen opens with the Import sheet. Nothing is sent
// anywhere from here; the upload happens signed in, from the page.
function stashShared(files) {
  return new Promise((resolve) => {
    const req = indexedDB.open('fishtape-share', 1);
    req.onupgradeneeded = () => { if (!req.result.objectStoreNames.contains('files')) req.result.createObjectStore('files', { autoIncrement: true }); };
    req.onerror = () => resolve();
    req.onsuccess = () => {
      const db = req.result;
      const t = db.transaction('files', 'readwrite');
      for (const f of files) t.objectStore('files').add({ name: f.name || 'Shared file', type: f.type || '', blob: f, at: Date.now(), via: 'share' });
      t.oncomplete = t.onerror = t.onabort = () => { db.close(); resolve(); };
    };
  });
}
self.addEventListener('fetch', (e) => {
  const url = new URL(e.request.url);
  if (e.request.method !== 'POST' || url.origin !== location.origin || url.pathname !== new URL('./share-target', self.registration.scope).pathname) return;
  e.respondWith((async () => {
    try {
      const form = await e.request.formData();
      const files = form.getAll('files').filter((f) => f && typeof f === 'object' && f.size > 0);
      if (files.length) await stashShared(files);
    } catch { /* nothing usable was shared */ }
    return Response.redirect(new URL('./#/files?shared=1', self.registration.scope).href, 303);
  })());
});
